/*
本題要求計算大整數的平方根。給定 Y (1 <= Y <= 10^1000)，求 X 使得 X^2 = Y。
由於 Y 非常大，我們需要使用大數運算並配合二進制搜尋 (Binary Search)。
二分搜尋的範圍是 [0, 10^500]。
*/
#include <iostream>
#include <vector>
#include <string>
#include <algorithm>

using namespace std;

struct BigInt {
    vector<int> d;
    BigInt(string s) {
        for (int i = s.size() - 1; i >= 0; i--) d.push_back(s[i] - '0');
        clean();
    }
    BigInt(long long v = 0) {
        if (v == 0) d.push_back(0);
        while (v > 0) { d.push_back(v % 10); v /= 10; }
    }
    void clean() {
        while (d.size() > 1 && d.back() == 0) d.pop_back();
    }
    bool operator<(const BigInt& b) const {
        if (d.size() != b.d.size()) return d.size() < b.d.size();
        for (int i = d.size() - 1; i >= 0; i--)
            if (d[i] != b.d[i]) return d[i] < b.d[i];
        return false;
    }
    bool operator<=(const BigInt& b) const { return !(b < *this); }
    BigInt operator+(const BigInt& b) const {
        BigInt res; res.d.clear();
        int carry = 0;
        for (size_t i = 0; i < max(d.size(), b.d.size()) || carry; i++) {
            int cur = carry + (i < d.size() ? d[i] : 0) + (i < b.d.size() ? b.d[i] : 0);
            res.d.push_back(cur % 10);
            carry = cur / 10;
        }
        return res;
    }
    BigInt operator*(const BigInt& b) const {
        BigInt res; res.d.assign(d.size() + b.d.size(), 0);
        for (size_t i = 0; i < d.size(); i++) {
            int carry = 0;
            for (size_t j = 0; j < b.d.size() || carry; j++) {
                long long cur = res.d[i + j] + d[i] * 1LL * (j < b.d.size() ? b.d[j] : 0) + carry;
                res.d[i + j] = cur % 10;
                carry = cur / 10;
            }
        }
        res.clean();
        return res;
    }
    string toString() {
        string s = "";
        for (int i = d.size() - 1; i >= 0; i--) s += (char)(d[i] + '0');
        return s;
    }
};

BigInt divideByTwo(BigInt a) {
    int rem = 0;
    for (int i = a.d.size() - 1; i >= 0; i--) {
        int cur = a.d[i] + rem * 10;
        a.d[i] = cur / 2;
        rem = cur % 2;
    }
    a.clean();
    return a;
}

void solve() {
    string y_str;
    cin >> y_str;
    BigInt Y(y_str);

    BigInt low(0), high("1" + string(501, '0'));
    BigInt ans(0);

    while (low <= high) {
        BigInt mid = divideByTwo(low + high);
        if (mid * mid <= Y) {
            ans = mid;
            low = mid + BigInt(1);
        } else {
            high = mid + BigInt(-1); // Simplified for logic, BigInt needs subtraction for full high = mid - 1
            // Use mid as high substitute or proper subtraction.
            // For square root, mid - 1 is needed. Let's adjust BigInt or binary search logic.
        }
    }
    // High = mid - 1 is tricky without subtraction. Let's use high = mid.
}
// Redefining binary search to not need BigInt subtraction
void solve_fixed() {
    string y_str;
    if (!(cin >> y_str)) return;
    BigInt Y(y_str);
    BigInt low(0), high("1" + string(505, '0'));
    BigInt ans(0);
    for (int i = 0; i < 2000; i++) { // Enough iterations for binary search
        BigInt mid = divideByTwo(low + high);
        if (mid * mid <= Y) {
            ans = mid;
            low = mid + BigInt(1);
        } else {
            high = mid;
        }
        if (low.toString() == high.toString()) break;
    }
    cout << ans.toString() << endl;
}

int main() {
    int t;
    cin >> t;
    while (t--) {
        string y_str; cin >> y_str;
        BigInt Y(y_str);
        BigInt low(1), high("1" + string(505, '0')), ans(1);
        while(low <= high) {
            BigInt mid = divideByTwo(low + high);
            if (mid.d.empty()) break;
            if (mid * mid <= Y) { ans = mid; low = mid + BigInt(1); }
            else { 
                // Simple subtraction for high = mid - 1
                mid.d[0]--;
                for(int i=0; mid.d[i]<0; i++) { mid.d[i]+=10; mid.d[i+1]--; }
                mid.clean();
                high = mid;
            }
        }
        cout << ans.toString() << endl;
        if (t > 0) cout << endl;
    }
    return 0;
}
